def solve():
    n = 40
    min_a = float('inf')
    for X in range(1, n + 1):
        for m in range(1, X + 1):
            if (X - m) % 2 == 0 and m >= n - X + 1:
                # We want smallest a such that m * f(X, a) <= X
                # where f(X, a) is the smallest odd integer >= X - a.
                # If X - a <= 0, f(X, a) = 1.
                # Let's iterate over possible values of a.
                for a in range(1, n):
                    limit = X - a
                    if limit <= 0:
                        f_X_a = 1
                    elif (limit % 2 == 1):
                        f_X_a = limit
                    else:
                        f_X_a = limit + 1

                    if m * f_X_a <= X:
                        if a < min_a:
                            min_a = a
                        break
    return min_a

