def find_max_d_v2(n):
    max_d = 0
    for s in range(n + 1):
        for d in range(n):
            # Smallest odd m >= d - s + 1
            m = d - s + 1
            if m <= 1:
                m = 1
            elif m % 2 == 0:
                m = m + 1
            else:
                m = m

            if (s + 2) * m <= n - s:
                if d > max_d:
                    max_d = d
    return max_d

