def check_possible(n, d, s):
    if n - s < s + 2:
        return False

    m = d - s + 1
    if m <= 1:
        m = 1
    elif m % 2 == 0:
        m = m + 1
    else:
        m = m

    if (s + 2) * m > n - s:
        return False

    k = s + 2
    if (n - s) % 2 == k % 2:
        o_large = n - s - (k - 1)
        sum_val = (k - 1) * d + o_large * (d - o_large + 1)
    else:
        o_large = n - s - (k - 2) - 3
        sum_val = (k - 2) * d + 3 * (d - 2) + o_large * (d - o_large + 1)

    return sum_val <= s * d

def solve():
    n = 40
    max_d = 0
    for d in range(n):
        for s in range(n):
            if check_possible(n, d, s):
                if d > max_d:
                    max_d = d
                    break
    return max_d

