def get_min_e(n, d, k):
    # n is the size of component C_i
    # d is the degree of the graph
    # k is the size of the set S
    # Condition: e_i >= n(d-n+1) if n <= d+1
    # Condition: e_i <= n*k
    # Condition: e_i % 2 == (n*d) % 2
    # Condition: if n > d+1, e_i = 0 if nd is even, 1 if nd is odd.

    if n > d + 1:
        if (n * d) % 2 == 0:
            e = 0
        else:
            e = 1
        if e <= n * k:
            return e
        else:
            return None
    else:
        e_low = n * (d - n + 1)
        # e_i must be >= e_low, e_i % 2 == (n*d) % 2
        # e_i must be <= n*k
        e = e_low
        if e % 2 != (n * d) % 2:
            e += 1
        if e <= n * k:
            return e
        else:
            return None

def solve():
    for d in range(39, 0, -1):
        for k in range(20):
            # DP to find minimum sum of e_i
            # dp[m][j] is the min sum of e_i for m components and j vertices
            # m in [k+2, 40-k]
            # j = 40-k
            max_m = 40 - k
            min_m = k + 2

            if min_m > max_m:
                continue

            # Precompute min_e for each possible n
            e_values = {}
            for n in range(1, 41):
                val = get_min_e(n, d, k)
                if val is not None:
                    e_values[n] = val

            # DP: dp[m][j]
            dp = [[float('inf')] * (41) for _ in range(max_m + 1)]
            dp[0][0] = 0

            for m in range(1, max_m + 1):
                for j in range(1, 41):
                    for n in range(1, j + 1):
                        if n in e_values:
                            if dp[m-1][j-n] != float('inf'):
                                dp[m][j] = min(dp[m][j], dp[m-1][j-n] + e_values[n])

            # Check if any valid m works
            for m in range(min_m, max_m + 1):
                res = dp[m][40-k]
                if res <= k * d and res <= k * (40-k):
                    print(f"Found d={d} with k={k}, min_e={res}")
                    return d
    return -1

