def solve():
    for d in range(39, 0, -1):
        for k in range(1, 39):
            n_min = max(1, d - k + 1)
            # dp[m][v] = set of possible sums of e_i
            dp = [[set() for _ in range(41)] for _ in range(41)]
            dp[0][0].add(0)

            # Possible odd n_i
            possible_n = [n for n in range(1, 41, 2) if n >= n_min]

            for m in range(1, 41):
                for v in range(1, 41):
                    for n in possible_n:
                        if v >= n:
                            for prev_sum in dp[m-1][v-n]:
                                # Calculate e for this n
                                min_e_val = max(0, n * (d - n + 1))
                                # e must be >= min_e_val, e <= n*k, and e % 2 == (n*d) % 2
                                # The smallest such e is:
                                e = min_e_val
                                if e % 2 != (n * d) % 2:
                                    e += 1

                                if e <= n * k and e <= n * d:
                                    dp[m][v].add(prev_sum + e)

            for m in range(k + 2, 41):
                if (m - k) % 2 == 0:
                    for v in range(1, 41):
                        # If d is odd, we need n_even to be even, so v % 2 == (40-k) % 2
                        # Actually v is sum of odd components. 40-k is total.
                        # n_even = 40-k-v. If n_even is even, 40-k-v is even.
                        # Since 40 is even, k-v is even, so v % 2 == k % 2.
                        if d % 2 == 1:
                            if v % 2 != k % 2:
                                continue

                        for s in dp[m][v]:
                            if k * (d - k + 1) <= s <= d * k:
                                return d, k, m, v, s
    return None

