def solve():
    for d in range(39, 0, -1):
        found_d = False
        for k in range(1, 40):
            for m in range(k + 2, 40 - k + 1):
                if m % 2 == k % 2:
                    X = max(1, d - k + 1)
                    X_odd = X if X % 2 == 1 else X + 1
                    if m * X_odd <= 40 - k:
                        # S_max
                        if k % 2 == d % 2:
                            S_max = (40 - k) * k
                        else:
                            S_max = (40 - k) * k - m

                        # S_min: maximize sum of n_i^2
                        # n_1 = n_2 = ... = n_{m-1} = X_odd
                        # n_m = 40 - k - (m-1) * X_odd
                        n_m = 40 - k - (m - 1) * X_odd
                        S_min = (m - 1) * X_odd * (d - X_odd + 1) + n_m * (d - n_m + 1)

                        # Intersection of [S_min, S_max] and [k*(d-k+1), k*d]
                        lower_bound = k * (d - k + 1)
                        upper_bound = k * d

                        if max(S_min, lower_bound) <= min(S_max, upper_bound):
                            print(f"Found d={d} with k={k}, m={m}, X_odd={X_odd}, S_min={S_min}, S_max={S_max}, bounds=[{lower_bound}, {upper_bound}]")
                            found_d = True
                            break
            if found_d:
                break
        if found_d:
            return 39 - d
    return None

