def solve():
    n = 40
    for d in range(39, 0, -1):
        for k in range(n):
            min_n = d - k + 1
            if min_n % 2 == 0:
                min_n += 1

            for m in range(k + 2, n - k + 1, 2):
                if m * min_n > n - k:
                    continue

                n_m = (n - k) - (m - 1) * min_n
                # n_m is always odd because n-k \equiv k (mod 2) and m-1 \equiv k-1 (mod 2)
                # and min_n is odd. So (n-k) - (m-1)*min_n \equiv k - (k-1)*1 = 1 (mod 2).

                max_sum_n_sq = (m - 1) * (min_n**2) + (n_m**2)
                min_sum_e_i = (d + 1) * (n - k) - max_sum_n_sq

                if min_sum_e_i <= d * k:
                    return d, k, m, min_n, n_m
    return None

